// SuiteRunsSchema returns the schema of agent_suite_runs.
func SuiteRunsSchema() *schema.Table { return &suiteRunsTable }

// As returns a handle that references agent_suite_runs under its own alias.
func (t *SuiteRunsTable) As(alias string) *SuiteRunsTable {
	return keel.Alias(t.Ref, alias, BuildSuiteRuns)
}

// Get returns the agent_suite_runs row with the given key, or keel.ErrNotFound.
func (t *SuiteRunsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*agentquality.SuiteRun, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newSuiteRun() unsafe.Pointer { return unsafe.Pointer(new(agentquality.SuiteRun)) }

func newNSuiteRun(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentquality.SuiteRun, n)))
}

func ptrSuiteRun(p unsafe.Pointer, c int32) any {
	r := (*agentquality.SuiteRun)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Trigger))
	case 5:
		return &r.SweepKey
	case 6:
		return &r.Fingerprint
	case 7:
		return &r.FingerprintHash
	case 8:
		return &r.FingerprintChanges
	case 9:
		return &r.SuiteRevision
	case 10:
		return &r.SampleSeed
	case 11:
		return (*string)(unsafe.Pointer(&r.Status))
	case 12:
		return (*int64)(unsafe.Pointer(&r.CasesTotal))
	case 13:
		return (*int64)(unsafe.Pointer(&r.CasesPassed))
	case 14:
		return (*int64)(unsafe.Pointer(&r.CasesFailed))
	case 15:
		return (*int64)(unsafe.Pointer(&r.CasesSkipped))
	case 16:
		return (*int64)(unsafe.Pointer(&r.HardFailures))
	case 17:
		return &r.DeterministicScore
	case 18:
		return &r.JudgeScore
	case 19:
		return &r.QualityScore
	case 20:
		return &r.BaselineScore
	case 21:
		return (**string)(unsafe.Pointer(&r.BaselineRunID))
	case 22:
		return &r.Regression
	case 23:
		return &r.CostUSD
	case 24:
		return &r.StartedAt
	case 25:
		return &r.FinishedAt
	case 26:
		return &r.Comments
	case 27:
		return &r.WorkflowID
	case 28:
		return (**string)(unsafe.Pointer(&r.RequestedByUserID))
	case 29:
		return &r.Version
	case 30:
		return &r.CreatedAt
	case 31:
		return &r.UpdatedAt
	}
	return nil
}

func valueSuiteRun(p unsafe.Pointer, c int32) any {
	r := (*agentquality.SuiteRun)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.AgentDefinitionID)
	case 4:
		return string(r.Trigger)
	case 5:
		if r.SweepKey == "" {
			return nil
		}
		return r.SweepKey
	case 6:
		if r.Fingerprint == nil {
			return nil
		}
		return *r.Fingerprint
	case 7:
		return r.FingerprintHash
	case 8:
		if r.FingerprintChanges == nil {
			return keel.EmptyJSONArray
		}
		return r.FingerprintChanges
	case 9:
		return r.SuiteRevision
	case 10:
		return r.SampleSeed
	case 11:
		return string(r.Status)
	case 12:
		return int64(r.CasesTotal)
	case 13:
		return int64(r.CasesPassed)
	case 14:
		return int64(r.CasesFailed)
	case 15:
		return int64(r.CasesSkipped)
	case 16:
		return int64(r.HardFailures)
	case 17:
		if r.DeterministicScore == nil {
			return nil
		}
		return *r.DeterministicScore
	case 18:
		if r.JudgeScore == nil {
			return nil
		}
		return *r.JudgeScore
	case 19:
		if r.QualityScore == nil {
			return nil
		}
		return *r.QualityScore
	case 20:
		if r.BaselineScore == nil {
			return nil
		}
		return *r.BaselineScore
	case 21:
		if r.BaselineRunID == nil {
			return nil
		}
		return string(*r.BaselineRunID)
	case 22:
		return r.Regression
	case 23:
		return r.CostUSD
	case 24:
		return r.StartedAt
	case 25:
		if r.FinishedAt == nil {
			return nil
		}
		return *r.FinishedAt
	case 26:
		if r.Comments == "" {
			return nil
		}
		return r.Comments
	case 27:
		if r.WorkflowID == "" {
			return nil
		}
		return r.WorkflowID
	case 28:
		if r.RequestedByUserID == nil {
			return nil
		}
		return string(*r.RequestedByUserID)
	case 29:
		return r.Version
	case 30:
		return r.CreatedAt
	case 31:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateSuiteRun(ctx context.Context, p unsafe.Pointer) error {
	return (*agentquality.SuiteRun)(p).BeforeCreate(ctx)
}

